const colorSchemeNames = Object.keys(COLOR_SCHEMES);
function isValidColorSchemeName(name) {
    return colorSchemeNames.includes(name);
}
const hexToIntColorRegexp = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i;
